function decodeEntities(str) {
  return str
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'")
    .replace(/&amp;/g, '&');
}

function parseAttributes(attrStr, prefix) {
  const attrs = {};
  const attrRe = /([A-Za-z_][\w:.-]*)\s*=\s*(?:"([^"]*)"|'([^']*)')/g;
  let m;
  while ((m = attrRe.exec(attrStr)) !== null) {
    const key = `${prefix}${m[1]}`;
    const rawVal = decodeEntities(m[2] ?? m[3] ?? '');
    attrs[key] = rawVal;
  }
  return attrs;
}

export class XMLParser {
  constructor(options = {}) {
    this.ignoreAttributes = options.ignoreAttributes ?? true;
    this.attributeNamePrefix = options.attributeNamePrefix ?? '@_';
    this.textNodeName = options.textNodeName ?? '#text';
    this.isArray = options.isArray ?? (() => false);
    this.trimValues = options.trimValues ?? true;
  }

  parse(xmlInput) {
    const xml = String(xmlInput)
      .replace(/<\?[\s\S]*?\?>/g, '')
      .replace(/<!--[\s\S]*?-->/g, '');

    const root = {};
    const stack = [{ tag: '__root__', node: root, path: '', text: '' }];
    const tokenRe = /<!\[CDATA\[([\s\S]*?)\]\]>|<\s*(\/)?\s*([A-Za-z_][\w:.-]*)([^>]*?)(\/)?\s*>|([^<]+)/g;

    let m;
    while ((m = tokenRe.exec(xml)) !== null) {
      if (m[1] !== undefined) {
        stack[stack.length - 1].text += m[1];
        continue;
      }
      if (m[6] !== undefined) {
        stack[stack.length - 1].text += decodeEntities(m[6]);
        continue;
      }

      const isClosing = Boolean(m[2]);
      const tagName = m[3];
      const attrPart = m[4] || '';
      const isSelfClosing = Boolean(m[5]);

      if (isClosing) {
        const finished = stack.pop();
        if (!finished) continue;
        const textVal = this.trimValues ? finished.text.trim() : finished.text;
        let finalValue = finished.node;

        const keys = Object.keys(finished.node);
        if (keys.length === 0) {
          finalValue = textVal;
        } else if (textVal.length > 0) {
          finished.node[this.textNodeName] = textVal;
        }

        const parent = stack[stack.length - 1];
        const jPath = parent.path ? `${parent.path}.${finished.tag}` : finished.tag;
        const forceArray = this.isArray(finished.tag, jPath, false, false);
        const existing = parent.node[finished.tag];
        if (existing !== undefined) {
          if (Array.isArray(existing)) {
            existing.push(finalValue);
          } else {
            parent.node[finished.tag] = [existing, finalValue];
          }
        } else if (forceArray) {
          parent.node[finished.tag] = [finalValue];
        } else {
          parent.node[finished.tag] = finalValue;
        }
        continue;
      }

      const newNode = this.ignoreAttributes
        ? {}
        : parseAttributes(attrPart, this.attributeNamePrefix);
      const parent = stack[stack.length - 1];
      const jPath = parent.path ? `${parent.path}.${tagName}` : tagName;

      if (isSelfClosing) {
        const forceArray = this.isArray(tagName, jPath, false, false);
        const value = Object.keys(newNode).length > 0 ? newNode : '';
        const existing = parent.node[tagName];
        if (existing !== undefined) {
          if (Array.isArray(existing)) existing.push(value);
          else parent.node[tagName] = [existing, value];
        } else if (forceArray) {
          parent.node[tagName] = [value];
        } else {
          parent.node[tagName] = value;
        }
      } else {
        stack.push({ tag: tagName, node: newNode, path: jPath, text: '' });
      }
    }

    return root;
  }
}
